@php
    $billing = $customerRequest->billing;
    $approvedServices = $customerRequest->requestServices->where('status', 'approved');
    $allDecided = $customerRequest->requestServices->every(fn ($item) => in_array($item->status, ['approved', 'rejected'], true));
    $rates = $approvedServices->pluck('gst_rate')->map(fn ($rate) => (string) $rate)->unique()->values();
    $defaultGstRate = old('gst_rate', $billing?->gst_rate ?? ($rates->count() === 1 ? $rates->first() : ($rates->first() ?? 0)));
    $allowedCharges = ['Stamp Duty', 'Registration Fee', 'Application Fee', 'Certified Copy Fee', 'Portal Fee', 'Search Fee', 'Other'];
    $defaultCharges = $approvedServices->flatMap(fn ($item) => collect($item->government_charges_snapshot ?? [])->map(fn ($charge, $index) => ['name' => in_array($charge['name'] ?? '', $allowedCharges, true) ? $charge['name'] : 'Other', 'amount' => $charge['amount'] ?? 0, 'note' => in_array($charge['name'] ?? '', $allowedCharges, true) ? ($charge['note'] ?? $charge['description'] ?? null) : trim(($charge['name'] ?? 'Government charge').' '.($charge['note'] ?? $charge['description'] ?? '')), 'display_order' => $index]));
    $chargeRows = old('government_charges', $billing?->charges?->map->only(['name','amount','note','display_order'])->all() ?? $defaultCharges->values()->all());
@endphp
