@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('request-billing-form');if(!form)return;const money=v=>'₹'+Number(v).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}),calc=()=>{const original=+form.dataset.original||0,type=form.elements.discount_type?.value||'none',value=+form.elements.discount_value?.value||0,discount=type==='fixed'?value:type==='percentage'?original*value/100:0,net=Math.max(0,original-discount),gst=net*(+form.elements.gst_rate?.value||0)/100,government=[...form.querySelectorAll('.charge-amount')].reduce((sum,input)=>sum+(+input.value||0),0);document.getElementById('bill-original').textContent=money(original);document.getElementById('bill-discount').textContent=money(discount);document.getElementById('bill-net').textContent=money(net);document.getElementById('bill-gst').textContent=money(gst);document.getElementById('bill-government').textContent=money(government);document.getElementById('bill-grand').textContent=money(net+gst+government)};form.addEventListener('input',calc);document.getElementById('billing-charge-rows')?.addEventListener('click',event=>{if(event.target.matches('.remove-billing-charge')){event.target.closest('.billing-charge-row').remove();calc()}});document.getElementById('add-billing-charge')?.addEventListener('click',()=>{const rows=document.getElementById('billing-charge-rows'),index=rows.querySelectorAll('.billing-charge-row').length,row=document.createElement('div');row.className='row g-2 mb-2 billing-charge-row';row.innerHTML=`<div class="col-md-3"><select name="government_charges[${index}][name]" class="form-select">${['Stamp Duty','Registration Fee','Application Fee','Certified Copy Fee','Portal Fee','Search Fee','Other'].map(v=>`<option>${v}</option>`).join('')}</select></div><div class="col-md-2"><input name="government_charges[${index}][amount]" type="number" min="0" step="0.01" class="form-control charge-amount" value="0"></div><div class="col-md-4"><input name="government_charges[${index}][note]" class="form-control" placeholder="Optional note"></div><div class="col-md-2"><input name="government_charges[${index}][display_order]" type="number" min="0" class="form-control" value="${index}"></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger remove-billing-charge">×</button></div>`;rows.append(row)});calc()});</script>@endpush